sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var score = 0;

    // 1. Evaluate Data Structure (Weight: 40 points)
    // GenAI thrives on unstructured data.
    var dataStructure = current.getValue('data_structure');
    if (dataStructure == 'unstructured') {
        score += 40;
    } else if (dataStructure == 'mixed') {
        score += 20;
    }

    // 2. Evaluate Decision Logic (Weight: 40 points)
    // GenAI is suited for complex, non-linear decisions.
    var decisionLogic = current.getValue('decision_logic');
    if (decisionLogic == 'requires_judgment') {
        score += 40;
    } else if (decisionLogic == 'mostly_rules') {
        score += 20;
    }

    // 3. Evaluate Human Judgement Level (Weight: 20 points)
    var judgement = current.getValue('human_judgement_level');
    if (judgement == 'expert_only_judgement') {
        score += 30;
    } else if (judgement == 'significant_judgement') {
        score += 20;
    }else if (judgement == 'some_judgement') {
        score += 10;
    }

    // 4. Security/Privacy Risk Penalty
    // If it contains PII, deduct points as it complicates the AI architecture.
    var containsPii = current.getValue('contains_pii');
    if (containsPii == 'true' || containsPii == '1') {
        score -= 10;
    }

    // 5. Clamp the score safely between 0 and 100
    score = Math.max(0, Math.min(100, score));

    // 6. Set the value on the record
	current.setValue('ai_suitability_score', score);

})(current, previous);
